    return {"id": id, "es": es, "en": en, "comidas": comidas, "porciones": porciones, "minutos": minutos,
            "ingredientes": [{"alimento": a, "gramos": g} for a, g in ingredientes], "pasosEs": pasos_es, "pasosEn": pasos_en}


