def principal():
    alimentos = {a["id"] for a in json.load(open(os.path.join(DATOS, "alimentos.json"), encoding="utf-8"))}
    ruta = os.path.join(DATOS, "recetas.json")
    recetas = json.load(open(ruta, encoding="utf-8"))
    ya = {x["id"] for x in recetas}
    nombres = {x["es"].lower() for x in recetas}
    nuevas = 0
    for rec in NUEVAS:
        faltan = [i["alimento"] for i in rec["ingredientes"] if i["alimento"] not in alimentos]
        assert not faltan, (rec["id"], faltan)
        assert len(rec["pasosEs"]) == len(rec["pasosEn"]), rec["id"]
        if rec["id"] in ya or rec["es"].lower() in nombres: continue
        recetas.append(rec); nuevas += 1
    json.dump(recetas, open(ruta, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("nuevas:", nuevas, "total:", len(recetas))


if __name__ == "__main__":
    principal()
